INSERT INTO exam_reports (grade, subject, exam_date, total, difficulty_level, scope, overview, sections, parent_guide)
VALUES (
  '중1', '영어',
  $q$2026. 7. 3.$q$,
  $q$32문항 (문법 20문항 / 독해 12문항)$q$,
  $q$합리적 난이도 (기본기 기반 고득점 가능)$q$,
  $q$중학교 1학년 1학기 진단 평가$q$,
  $q$초등 과정에서 다져온 기본 문법 개념을 중학교 수준으로 확장하여 점검하는 데 중점을 두었습니다. 특히 상태동사의 진행형 제한과 같이 초등 과정에서는 다루지 않았던 세밀한 문법 규칙을 포함하여, 단순 암기가 아닌 규칙의 원리를 이해하고 있는지를 변별하고자 하였습니다. 독해 영역에서는 단순한 사실 확인을 넘어, 지문에 제시된 정보를 종합하여 추론하고 필자의 의도를 파악하는 능력을 요구하는 문항이 다수 포함되었습니다. 특히 과학적 원리를 설명하는 지문과 사회적 이슈를 다루는 지문을 함께 배치함으로써, 학생들이 다양한 유형의 정보 전달형 글에 얼마나 유연하게 대응할 수 있는지를 평가하고자 하였습니다. 전체적인 난이도는 기본 개념을 정확히 학습한 학생과 그렇지 않은 학생 간의 실력 차이가 비교적 뚜렷하게 드러날 수 있도록 설계되었습니다. 문항의 배점과 구성을 고려할 때, 성실하게 기본기를 다진 학생이라면 충분히 고득점이 가능한 합리적인 난이도로 평가됩니다.$q$,
  $j$[{"title": "출제 범위", "type": "list", "items": ["【문법】 동사의 시제와 형태 — 현재/과거/미래 시제, 동사 규칙·불규칙 변화형, 상태동사의 진행형 제한(중학 신규 강조)", "【문법】 대명사 — 인칭대명사·소유격·지시대명사 등의 격 변화와 문맥에 맞는 쓰임", "【문법】 비교구문 — 원급, 비교급, 최상급 표현의 형태 변화와 문맥상 적절한 활용", "【문법】 전치사 — 시간, 장소, 방향 뿐 아니라 다양한 전치사의 정확한 쓰임", "【독해】 정보 전달형 지문 — 동물의 생태(악어의 눈물), 과학 실험(시리얼 속 철분과 자석 실험), 사회 캠페인(Earth Hour) 등 다양한 소재의 세부 정보 파악 및 추론"]}, {"title": "문항별 난이도 분석", "type": "difficulty", "rows": [{"level": "상", "color": "red", "items": "8, 11, 18, 22, 30, 31번", "desc": "상태동사의 진행형 제한(8번) / be going to의 현재진행형·미래형 구분(11번) / 대화문 속 오류를 찾아 고치기(18번) / 지시대명사가 가리키는 내용 서술하기(22, 30, 31번)"}, {"level": "중", "color": "yellow", "items": "4, 9, 10, 14, 17, 19, 21, 23~29, 32번", "desc": "비교 표현/be동사의 의미(10, 14, 17, 19번) / 시제 및 수 일치(4, 9번) / 빈칸 추론(21, 25, 29, 32번) / 세부 내용 파악(24, 27번) / 지문의 주제(23번)와 제목(28번) 파악"}, {"level": "하", "color": "green", "items": "나머지 문항", "desc": "대명사(5, 6, 7, 12, 13번) / 동사의 과거형·-ing형 변화(1, 2번) / 비교급·최상급의 기본 형태(3번) / 다양한 전치사 기본 쓰임(15, 16번) / 현재진행형 영작(20번)"}]}, {"title": "핵심 학습 포인트 및 향후 방향", "type": "keypoints", "items": [{"title": "동사의 활용 (상태동사 진행형 제한)", "desc": "감각·인지·소유를 나타내는 동사는 진행형으로 쓰이지 않는다는 규칙은 중학교 문법의 핵심 개념 — 각 동사가 가지는 의미와 특성을 이해하고 문맥에 활용하는 학습 필요", "num": "01"}, {"title": "비교구문의 문맥적 활용", "desc": "원급, 비교급, 최상급의 형태를 아는 것에서 나아가 실제 문장 속에서 어떤 표현이 적절한지 판단하는 연습 필요", "num": "02"}, {"title": "정보 전달형 지문 독해력", "desc": "과학적 원리나 사회적 이슈를 다루는 지문에서 핵심 정보를 정확히 파악하고, 이를 바탕으로 필자의 의도나 다음 내용을 추론하는 훈련 필요", "num": "03"}]}]$j$::jsonb,
  $q$앞으로는 중학교 문법 체계에서 자주 다뤄지는 세부 규칙을 개념 중심으로 정리하고, 다양한 소재의 지문을 꾸준히 접하며 추론적 독해 능력을 함께 길러나가는 학습이 필요합니다. 이를 위해 자녀가 문법 규칙을 단순히 암기하기보다 그 원리를 이해하고 있는지 확인해 주시고, 다양한 주제의 영어 지문을 접할 기회를 늘려 독해에 대한 자신감을 키워주시기를 권장드립니다.$q$
)
ON CONFLICT (grade, subject) DO UPDATE SET
  exam_date = EXCLUDED.exam_date,
  total = EXCLUDED.total,
  difficulty_level = EXCLUDED.difficulty_level,
  scope = EXCLUDED.scope,
  overview = EXCLUDED.overview,
  sections = EXCLUDED.sections,
  parent_guide = EXCLUDED.parent_guide,
  updated_at = now();

INSERT INTO exam_reports (grade, subject, exam_date, total, difficulty_level, scope, overview, sections, parent_guide)
VALUES (
  '초5', '수학',
  $q$2026. 7. 3.$q$,
  $q$24문항 (객관식 및 주관식 혼합 100%)$q$,
  $q$중상(中上)$q$,
  $q$분수, 다각형의 둘레와 넓이$q$,
  $q$이번 초등학교 5학년 2학기 기말고사는 '단순한 공식 암기를 넘어선 개념의 상호 연계 능력과 다단계 문장제 문제 해결 능력'을 평가하는 데 초점을 맞추었습니다. 5학년 수학은 중·고등 수학의 기초가 되는 '약수와 배수, 통분, 다각형의 넓이'가 본격적으로 융합되는 시기이므로 변별력 있는 문항들이 다수 배치되었습니다. 분수 파트에서는 단순 계산뿐만 아니라 조건에 맞는 기약분수의 개수를 구하거나 일정한 규칙성을 찾아내는 논리적 사고력이 요구되었습니다. 도형 파트에서는 기본적인 사각형의 넓이 공식 적용부터, 단위가 다른 차원(cm와 m)의 혼합 계산, 그리고 복잡하게 얽힌 다각형의 넓이를 쪼개거나 붙여서 해결하는 통합적 문제 해결 능력이 필요했습니다. 전체적인 난이도는 '중상(中上)' 수준이며, 정확한 연산력과 문제 독해력을 고루 갖춘 학생만이 고득점을 선점할 수 있도록 출제되었습니다.$q$,
  $j$[{"title": "출제 범위", "type": "list", "items": ["【분수 단원】 크기가 같은 분수 만들기, 분수의 통분 및 크기 비교, 기약분수 구하기, 분수의 덧셈과 뺄셈 (대분수 및 세 분수의 계산 포함)", "【다각형의 둘레와 넓이 단원】 정사각형·평행사변형·직사각형·마름모의 둘레와 넓이 구하기, 복잡한 다각형(L자형 등)의 둘레 및 넓이 응용"]}, {"title": "문항별 난이도 분석", "type": "difficulty", "rows": [{"level": "상", "color": "red", "items": "21, 22, 23, 24번", "desc": "조건 범위 내 만족하는 분모가 45인 기약분수 개수 구하기(21번) / 대각선 성질을 이용한 정사각형 확장 및 색칠된 넓이 구하기(22번) / 수열의 규칙을 파악하여 알맞은 기약분수 추론하기(23번) / 실생활 단위(갤런, 쿼트 등) 변환을 통한 최적의 가격 조건 도출 문장제(24번)"}, {"level": "중", "color": "yellow", "items": "7, 9, 13, 15, 17, 18, 19, 20번", "desc": "분수와 소수의 크기 비교 및 분모가 다른 대분수의 덧셈(7, 9번) / cm와 m 단위를 일치시켜 직사각형 넓이 구하기(13번) / 주어진 조건(둘레)을 활용해 두 정사각형의 한 변의 길이 차이 구하기(18번) / L자형 도형의 둘레 및 복합 다각형의 넓이 분할 계산(19, 20번)"}, {"level": "하", "color": "green", "items": "나머지 12개 문항", "desc": "크기가 같은 분수 만들기 및 공통분모 통분 기초(1, 2, 3, 5, 6번) / 삼각형의 높이 찾기 및 정다각형·평행사변형·마름모의 기본 둘레와 넓이 공식 적용(4, 11, 12, 14번)"}]}, {"title": "핵심 학습 포인트 및 향후 방향", "type": "keypoints", "items": [{"title": "연산 실수를 줄이는 '정확한 통분과 단위 환산 능력'", "desc": "단순히 분수의 덧·뺄셈 공식을 외우는 것을 넘어 분모가 다른 세 분수의 계산(10번)이나, cm와 m가 혼재된 넓이 계산(13번)처럼 사소한 변수를 스스로 통제할 수 있어야 합니다. 향후 분수의 곱셈과 나눗셈으로 확장될 때 치명적인 오답 요인이 되므로 철저한 단위 점검 습관이 필요합니다.", "num": "01"}, {"title": "도형을 분할하고 시각화하는 '공간적 문제 해결력'", "desc": "22번(정사각형 응용)이나 19, 20번(복잡한 다각형)처럼 정형화되지 않은 도형이 제시되었을 때, 보조선을 긋거나 아는 도형의 형태로 쪼개어 접근하는 훈련이 핵심이었습니다. 공식을 기계적으로 대입하는 버릇을 버리고 문제의 조건을 그림에 매칭하는 연습을 지속해야 합니다.", "num": "02"}]}]$j$::jsonb,
  $q$5학년 2학기 수학은 초등 수학 중 가장 고비가 되는 구간입니다. 현재 아이가 틀린 문항이 '단순한 공식 암기 부족(난이도 하)'의 문제인지, '조건이 누적된 문장제 독해 및 응용력 부족(난이도 상)' 때문인지 명확히 진단해야 합니다. 대치 프라임에서는 오답 노트를 활용하여, 복잡한 문장제 문제도 스스로 식을 세우고 논리 단계를 설명할 수 있을 때까지 1:1 밀착 관리를 진행하겠습니다.$q$
)
ON CONFLICT (grade, subject) DO UPDATE SET
  exam_date = EXCLUDED.exam_date,
