  updated_at = now();

INSERT INTO exam_reports (grade, subject, exam_date, total, difficulty_level, scope, overview, sections, parent_guide)
VALUES (
  '중1', '과학',
  $q$2026. 7. 3.$q$,
  $q$25문항 (객관식 100%)$q$,
  $q$중상(中上)$q$,
  $q$생물의 다양성, 열과 우리 생활$q$,
  $q$이번 7월 진단 평가는 '단순 암기가 아닌, 과학적 원리의 이해와 자료 해석 능력'을 묻는 데 초점을 맞추었습니다. 생물 파트에서는 분류 기준에 따라 생물을 정확히 구별해 내는 논리력(검색표 해석)과 생태계 먹이사슬의 상호작용을 이해하는 통합적 사고력이 요구되었습니다. 열 파트에서는 실생활에서 일어나는 열의 이동 현상을 전도, 대류, 복사 개념과 정확히 매칭하고, 열평형 그래프를 분석하는 문항들이 출제되었습니다. 전반적인 난이도는 '중상(中上)' 수준이며, 개념을 완벽히 숙지하고 이를 새로운 실험 조건이나 그래프에 적용해 본 학생만이 고득점을 받을 수 있도록 변별력 있게 구성되었습니다.$q$,
  $j$[{"title": "출제 범위", "type": "list", "items": ["【2단원】 생물의 다양성 — 생물 다양성과 변이, 생물의 분류(5계), 생물 다양성 보전", "【3단원】 열과 우리 생활 — 온도와 입자의 운동, 열의 이동(전도, 대류, 복사), 열평형, 비열과 열팽창(기초)"]}, {"title": "문항별 난이도 분석", "type": "difficulty", "rows": [{"level": "상", "color": "red", "items": "11, 16, 21, 24, 25번", "desc": "열평형 그래프 해석 및 실험 조건 비교(16, 25번) / 복잡한 생태계 먹이사슬 분석(11번) / 열의 이동 방향을 통한 온도 대소 비교(21, 24번)"}, {"level": "중", "color": "yellow", "items": "1, 4, 8, 9, 12, 22번", "desc": "갈라파고스 땅거북의 자연 선택 과정(1번) / 생물 분류 검색표 작성 및 해석(8, 9번) / 식물·동물 세포 구조의 차이점(12번)"}, {"level": "하", "color": "green", "items": "나머지 14개 문항", "desc": "생물계(5계)의 기본 특징, 열의 이동 방식 기본 개념 등 교과서 수준의 필수 암기 사항"}]}, {"title": "특이사항", "type": "list", "items": ["문항 9번은 '핵막 유무 → 균사 구조 → 기관 발달'의 분류 흐름을 정확히 이해해야 합니다.", "문항 25번은 실험 데이터를 해석해 단열 효과를 비교하는 고난도 응용형으로, 학생들의 과학적 분석력 차이를 명확히 드러냈습니다."]}, {"title": "학습했어야 할 중요 포인트 및 향후 학습 방향", "type": "keypoints", "items": [{"title": "텍스트를 넘어선 '시각 자료' 해석 능력", "desc": "단순히 '균계는 균사로 이루어져 있다'를 아는 것을 넘어, 표(4번)나 다단계 검색표(8, 9번)로 제시되었을 때 배운 개념을 정확히 대입할 수 있어야 합니다.", "num": "01"}, {"title": "'왜?'라는 질문에 답할 수 있는 원리 이해", "desc": "열평형 단원에서는 두 물체를 접촉했을 때 온도가 같아지는 현상뿐만 아니라, 입자의 운동 상태가 어떻게 변하는지(23번) 미시적인 관점에서 이해하는 것이 핵심이었습니다.", "num": "02"}]}, {"title": "단원별 학습 조언", "type": "keypoints", "items": [{"num": "2단원", "title": "생물의 다양성 단원", "desc": "핵심 개념: 종의 정의(자연 상태에서 번식 가능한 생물 무리), 생물 분류 체계(계–문–강–목–과–속–종), 생물 다양성의 의의와 보전. 학습 조언: 단순 분류 암기보다 '분류 기준이 왜 필요한가'를 이해해야 합니다. 외래종 문제나 생태계 평형 관련 문항은 실제 사례를 통해 사고력을 키우는 것이 효과적입니다."}, {"num": "3단원", "title": "열과 우리 생활 단원", "desc": "핵심 개념: 열의 이동 방향(고온→저온), 열평형, 전도·대류·복사 구분, 단열과 보온의 원리. 학습 조언: 그래프 해석 능력을 강화해야 합니다. 온도 변화 곡선에서 열평형 구간을 찾는 연습이 필요합니다. 실험 결과를 수치로 비교하는 문제(예: 시험관 온도 변화)는 단순 계산보다 '열 이동의 원리'를 설명할 수 있어야 합니다."}]}]$j$::jsonb,
  $q$우리 아이가 틀린 문항이 '단순 개념 암기 부족(난이도 하)'인지, '자료 해석 및 응용력 부족(난이도 상)'인지 파악하는 것이 중요합니다. 대치 프라임에서는 오답 노트를 통해 아이들이 부족한 개념을 스스로 설명할 수 있을 때까지 밀착 지도할 예정입니다.$q$
)
ON CONFLICT (grade, subject) DO UPDATE SET
