  parent_guide = EXCLUDED.parent_guide,
  updated_at = now();

INSERT INTO exam_reports (grade, subject, exam_date, total, difficulty_level, scope, overview, sections, parent_guide)
VALUES (
  '중1', '수학',
  $q$2026년 7월$q$,
  $q$24문항 (객관식 20문항 / 주관식 2문항 / 서술형 2문항)$q$,
  $q$개념 이해 및 출제 의도 파악 중심$q$,
  $q$문자와 식 ~ 정비례와 반비례$q$,
  $q$이번 진단평가는 학생들이 개념을 얼마나 정확하게 이해하고 있는지, 그리고 처음 접하는 문제에서도 배운 개념을 스스로 적용할 수 있는지를 확인하는 데 중점을 두었습니다. 평소 학생들은 학원에서 매쓰플랫시스템을 활용하여 다양한 유형의 문제를 반복적으로 학습해 왔습니다. 반복 학습은 기본기를 다지는 데 매우 효과적이지만, 동일하거나 유사한 유형에 익숙해질 가능성도 있습니다. 이에 이번 시험은 기존 문제은행 문항을 그대로 활용하지 않고, 중1-1 A급 수학, 중1-1 라이트쎈, 단국대학교부속중학교 기출문제를 참고하여 교육과정에 맞는 문항을 선별하고 새롭게 재구성하여 출제하였습니다. 특히 학생들이 풀이 방법을 기억했는지를 평가하기보다, 문제의 출제 의도를 파악하고 적절한 개념을 선택하여 해결할 수 있는지를 확인하는 데 초점을 맞추었습니다. 최근 학교 수학 평가 역시 단순 계산 능력뿐 아니라 개념 이해와 문제 해결 과정을 중요하게 평가하는 방향으로 운영되고 있습니다. 이에 맞추어 이번 시험 또한 암기식 풀이보다 개념을 이해하고 사고하는 능력을 평가할 수 있도록 구성하였습니다.$q$,
  $j$[{"title": "출제 범위", "type": "list", "items": ["문자와 식", "식의 계산 및 동류항", "일차방정식", "좌표와 좌표평면", "정비례와 반비례"]}, {"title": "문항별 난이도 분석", "type": "difficulty", "rows": [{"level": "상", "color": "red", "items": "5, 23, 24번", "desc": "출제 의도를 스스로 파악하여 여러 개념을 연결해야 해결 가능한 사고력 중심 문항"}, {"level": "중", "color": "yellow", "items": "3, 6~16, 18번", "desc": "핵심 개념을 이해하고 문제 상황에 적용하는 능력을 평가하는 응용 문항"}, {"level": "하", "color": "green", "items": "1, 2, 4, 17, 19, 20, 21, 22번", "desc": "문제에서 무엇을 묻는지가 명확하게 드러나는 기본 개념 확인 문항"}]}, {"title": "이번 시험의 핵심 학습 포인트", "type": "keypoints", "items": [{"title": "개념을 정확하게 이해하는 학습", "desc": "공식이나 풀이 방법을 암기하는 것보다 왜 그렇게 풀이하는지를 이해하는 학습이 중요합니다.", "num": "01"}, {"title": "문제의 출제 의도를 읽는 연습", "desc": "응용 문제는 계산보다 먼저 어떤 개념을 적용해야 하는지를 판단하는 과정이 중요합니다.", "num": "02"}, {"title": "풀이 과정을 설명하는 습관", "desc": "정답을 맞히는 것에서 끝나는 것이 아니라, 풀이 과정을 스스로 설명할 수 있을 정도의 이해가 필요합니다.", "num": "03"}, {"title": "다양한 유형 경험하기", "desc": "익숙한 유형뿐 아니라 새로운 문제에서도 배운 개념을 적용하는 연습을 꾸준히 하는 것이 중요합니다.", "num": "04"}]}]$j$::jsonb,
  $q$이번 진단평가는 단순히 점수를 확인하기 위한 시험이 아니라, 학생이 개념을 얼마나 정확하게 이해하고 새로운 문제에서도 이를 활용할 수 있는지를 확인하기 위한 평가였습니다. 대치프라임에서는 시험 결과를 바탕으로 학생별 부족한 개념과 취약 유형을 분석하고, 오답을 스스로 설명할 수 있을 때까지 개념 중심의 피드백을 진행하여 다음 평가에서 실질적인 성장을 이끌어낼 수 있도록 지도하겠습니다.$q$
)
