INSERT INTO exam_reports (grade, subject, exam_date, total, difficulty_level, scope, overview, sections, parent_guide)
VALUES (
  '중1', '국어',
  $q$2026. 7. 3.$q$,
  $q$34문항 (45분)$q$,
  $q$중상 (3단계 구성)$q$,
  $q$1학기 과정 (자유학기제 및 중등 첫 내신 대비 평가)$q$,
  $q$본 평가는 초등 국어의 단순 사실적 이해를 넘어, 중학교 내신 및 수능형 독해의 초석이 되는 '문학적 개념 적용력'과 '비문학 독해의 구조화 역량'을 정밀하게 평가하도록 설계되었습니다. 학생들이 중등 진학 후 가장 생소해하는 시의 표현 방법(역설, 반어, 직유, 은유 등), 소설의 시점 변화에 따른 서사 이해, 그리고 비문학 지문의 논리적 인과 관계를 파악하는 문항을 집중 배치하였습니다. 특히 감점 기준이 까다로운 중등 서술형 평가 조건(어절 제한, 핵심 어휘 매칭)을 엄격히 적용하여, 향후 치러질 중학교 지필평가에서 실전 실수를 방지하고 감점을 최소화하는 꼼꼼함을 함께 검증하였습니다.$q$,
  $j$[{"title": "문학(시·소설) 출제 범위", "type": "list", "items": ["현대시 (성장 및 성찰 주제 시 변형) — 비유적 표현(직유·은유) 및 역설적 어조의 효과 파악", "현대소설 (중1 주요 교과 수록 소설) — 시점의 특징(1인칭과 3인칭) 및 인물 간의 갈등 양상 분석", "문학 개념어 — 운율 형성 요소, 반어와 역설의 개념적 구별"]}, {"title": "독해(비문학) 및 어휘 출제 범위", "type": "list", "items": ["설명문 (청소년기 뇌 과학의 특징) — 각 단락의 중심 내용 파악 및 핵심 요약", "논설문 (디지털 리터러시의 필요성) — 글쓴이의 관점(비판/옹호) 및 논리적 오류 찾아내기", "어휘·문법 — 품사의 개념(체언, 용언 등 기본 구분) 및 문맥에 따른 정확한 단어 선택"]}, {"title": "문항별 난이도 분석", "type": "difficulty", "rows": [{"level": "상", "color": "red", "items": "6, 13, 21, 22, 27, 30, 31번", "desc": "시점 변화에 따른 서술상 특징 추론, 비문학 복합 조건형 서술형 문항 — 상위권 변별 핵심 문항군"}, {"level": "중", "color": "yellow", "items": "2, 3, 4, 5, 8~11, 14, 15, 17, 18, 20, 23~26, 28, 29, 32, 33번", "desc": "지문 내 인과 관계 파악, 문학 개념어의 실제 작품 적용 — 개념 이해를 바탕으로 한 실전 적용 훈련 필요"}, {"level": "하", "color": "green", "items": "1, 7, 12, 16, 19, 34번", "desc": "시어의 표면적 의미 파악, 비문학 사실적 일치 확인, 기본 어휘 — 정규 수업에 충실했다면 직관적으로 해결 가능"}]}, {"title": "핵심 학습 포인트 및 향후 방향", "type": "keypoints", "items": [{"title": "문학 개념어의 실전 작품 적용", "desc": "반어, 역설, 표현 기법 등 교과서적 정의를 외우는 것에 그치지 않고, 처음 보는 낯선 시나 소설의 구절에서 해당 기법을 스스로 찾아내는 훈련 강화 (4, 5, 22번 출제)", "num": "01"}, {"title": "비문학 독해의 구조화 및 거시적 안목", "desc": "단순히 문장을 읽어 내려가는 것이 아니라, 문단 간의 연결 고리(원인-결과, 주장-근거)를 파악하고 글 전체의 뼈대를 세우는 독해력 요구 (9, 11, 13, 17, 23번 출제)", "num": "02"}, {"title": "중등 품사 및 어휘 기본기", "desc": "중등 국어 문법의 핵심인 품사의 특성을 이해하고, 문맥 속에서 올바른 문장 성분으로 기능하는지 구별하는 문법 기초 확립 (2, 3, 10, 14, 24, 25, 28번 출제)", "num": "03"}, {"title": "중등 내신형 조건부 서술형 대비", "desc": "지문 속 핵심 키워드를 반드시 포함하되, 학교 내신에서 요구하는 구체적 조건(특정 어절 이내, 완결된 문장 구조)을 완벽히 충족하여 감점을 원천 차단하는 서술 훈련 (26~30번 출제)", "num": "04"}]}]$j$::jsonb,
  $q$중학교 국어는 초등 시절의 '감'으로 푸는 국어와 완전히 결별해야 하는 시기입니다. 교과서 핵심 개념(시점, 비유, 품사 등)이 용어로서 명확히 정립되어 있어야 지필평가에서 무너지지 않습니다. 자유학기제 기간이라도 방심하지 않고 비문학 독해 매일 풀기, 문학 작품 속 개념 찾기 등 자기주도적 독해 습관을 유지할 수 있도록 가정에서도 지속적인 관심과 격려를 부탁드립니다.$q$
)
ON CONFLICT (grade, subject) DO UPDATE SET
  exam_date = EXCLUDED.exam_date,
  total = EXCLUDED.total,
  difficulty_level = EXCLUDED.difficulty_level,
  scope = EXCLUDED.scope,
  overview = EXCLUDED.overview,
  sections = EXCLUDED.sections,
  parent_guide = EXCLUDED.parent_guide,
  updated_at = now();

INSERT INTO exam_reports (grade, subject, exam_date, total, difficulty_level, scope, overview, sections, parent_guide)
VALUES (
  '초5', '국어',
  $q$2026. 7. 3.$q$,
  $q$34문항 (45분)$q$,
  $q$중상 (3단계 구성)$q$,
  $q$1학기 기말고사$q$,
  $q$본 평가는 단순한 지문 암기와 단편적인 어휘 암기를 넘어, 낯선 지문 속에서 글의 핵심 맥락을 관통하고, 조건에 맞추어 자신의 생각을 논리적인 문장으로 기술할 수 있는지를 정밀하게 평가하도록 설계되었습니다. 특히 학생들이 실전에서 가장 많이 실수하는 '글의 전개 방식 파악', '다양한 의미를 지닌 다의어 구분', '핵심 요약을 위한 조건 서술형' 문항을 집중 배치하였습니다. 이번 시험은 개념의 정확한 이해와 더불어 감점 요인을 피하는 꼼꼼함을 함께 평가하였으며, 이는 향후 중등 국어 내신 및 지문 독해력과 직결되는 핵심 역량입니다.$q$,
  $j$[{"title": "독해 및 어휘 출제 범위", "type": "list", "items": ["설명문 (우주 쓰레기 문제와 해결책) — 글의 구조 파악 및 중심 생각 찾기", "논설문 (인공지능 시대의 윤리적 쟁점) — 글쓴이의 주장과 근거의 적절성 판단", "문학 (현대 소설 - 자전거 도둑 변형) — 인물의 심리 변화 및 복선 이해", "어휘·어문 규정 (다의어와 동음이의어) — 문맥에 맞는 단어의 의미 구별"]}, {"title": "서술형 및 문법 출제 범위", "type": "list", "items": ["문장 성분 간의 호응 관계 (주어-서술어 호응)", "글의 전개 방식에 따른 요약문 완성", "인과 관계를 나타내는 접속어의 올바른 활용", "제시된 조건(단어 포함, 글자 수 제한)에 맞춘 주제문 서술"]}, {"title": "문항별 난이도 분석", "type": "difficulty", "rows": [{"level": "상", "color": "red", "items": "6, 13, 21, 22, 27, 30, 31번", "desc": "복합 조건 서술형 영작 및 독해 추론 문항 — 상위권 변별을 위한 핵심 문항군"}, {"level": "중", "color": "yellow", "items": "2, 3, 4, 5, 8~11, 14, 15, 17, 18, 20, 23~26, 28, 29, 32, 33번", "desc": "핵심 어휘 및 문맥적 의미 적용 능력 확인 — 지문 내 중심 내용 매칭 훈련 필요"}, {"level": "하", "color": "green", "items": "1, 7, 12, 16, 19, 34번", "desc": "사실적 정보 확인, 기본 맞춤법 및 문장 성분 — 수업에 충실히 참여했다면 무난히 해결 가능"}]}, {"title": "핵심 학습 포인트 및 향후 방향", "type": "keypoints", "items": [{"title": "문맥적 어휘력과 다의어 구별", "desc": "단순히 단어의 사전적 정의를 외우는 것을 넘어, 문장 속 자리와 문맥에 따라 다르게 쓰이는 다의어의 의미를 정확히 구별하는 능력 요구 (4, 5, 22번 출제)", "num": "01"}, {"title": "글의 구조 파악과 요약 능력", "desc": "원인과 결과, 비교와 대조 등 설명문과 논설문의 핵심 구조를 분석하고, 이를 바탕으로 중심 내용을 한 줄로 요약하는 훈련 필요 (9, 11, 13, 17, 23번 출제)", "num": "02"}, {"title": "문장 성분의 호응과 어문 규정", "desc": "주어와 서술어의 호응, 조사 사용의 적절성 등 중등 내신 서술형에서 감점 단골 요소가 되는 문장의 구조적 정확성 강화 (2, 3, 10, 14, 24, 25, 28번 출제)", "num": "03"}, {"title": "조건 기반 논리 서술 (서술형)", "desc": "글자 수 제한, 필수 어휘 포함, 완결된 문장 형태(~다로 끝낼 것) 등 복합 조건을 누락 없이 충족하는 서술형 대비 훈련 (26~30번 출제)", "num": "04"}]}]$j$::jsonb,
  $q$초등 고학년 국어는 중등 내신으로 넘어가는 가장 중요한 징검다리입니다. 단순히 책을 많이 읽는 것을 넘어, 비문학 지문을 읽고 중심 문장에 밑줄을 그으며 구조화하는 습관이 필요합니다. 서술형 문항의 감점을 줄이기 위해 평상시 문제를 풀 때도 핵심 키워드를 포함하여 완전한 문장으로 답을 직접 써보는 서술 훈련을 가정에서도 독려해 주시길 권해드립니다.$q$
)
ON CONFLICT (grade, subject) DO UPDATE SET
  exam_date = EXCLUDED.exam_date,
  total = EXCLUDED.total,
  difficulty_level = EXCLUDED.difficulty_level,
  scope = EXCLUDED.scope,
  overview = EXCLUDED.overview,
  sections = EXCLUDED.sections,
  parent_guide = EXCLUDED.parent_guide,
  updated_at = now();

